INSERT INTO changelog (title, body, created_at) VALUES ('Автоісторія і «Підтверди» ширше', 'Що додали:
- Автоматично в Історію (з позначкою «авто», можна видалити): кампанію в Meta запустили або поставили на паузу; оновили брендбук; додали / імпортували конкурентів; ти скинув у групу файл з підписом «зробив… / готово…».
- Черга «Підтверди» тепер ще й без ШІ (безкоштовно, щодня о 19:00): задача, де всі пункти виконані, але вона відкрита → «закрити»; прострочений «Наступний крок» → «зроблено?»; у стратегії написано «реклама на паузі», а в Meta є витрати → «оновити стратегію».
- Попросити Джері «звір чергу Підтверди для <клієнт>» — перевірить одразу (правила + переписка).', datetime('now'));
